<template>
  <aside class="music-dock engraved-music" :class="{expanded}" aria-label="云间留声背景音乐台">
    <audio ref="audio" preload="metadata" @loadedmetadata="readDuration" @durationchange="readDuration" @timeupdate="readTime" @play="playing=true" @pause="playing=false" @ended="step(1)" @error="onError" />
    <button v-if="!expanded" class="music-pearl" type="button" aria-label="展开背景音乐播放台" @click="expanded=true"><span :class="{spinning:playing}">♫</span><span>云间留声</span><i>{{playing?'播放中':'音乐'}}</i></button>
    <Transition name="folio-float"><section v-if="expanded" id="music-console" class="music-console"><div class="music-frontispiece" aria-hidden="true"><EtchedOrnament kind="sound"/><span>留声 / 旅途旋律</span><i :class="{active:playing}" :style="{rotate:(duration?position/duration*240-120:-120)+'deg'}"/></div>
      <header><div class="music-disc" :class="{spinning:playing}" aria-hidden="true"><EtchedOrnament kind="sound"/></div><div class="music-heading"><small>留声 · 旅途旋律</small><strong :title="track.title">{{track.title}}</strong><p role="status">{{error || (playing?'旋律流转，故事未歇。':'轻触播放，让音乐陪伴旅程。')}}</p></div><button class="music-icon" aria-label="收起音乐播放台" @click="expanded=false">⌄</button></header>
      <div class="music-timeline"><input aria-label="播放进度" type="range" min="0" :max="duration || 1" step="0.1" :value="position" :disabled="!duration" @input="seek(Number($event.target.value))" /><div><time>{{format(position)}}</time><time>{{format(duration)}}</time></div></div>
      <div class="music-controls"><button aria-label="上一首" @click="step(-1)">⏮</button><button aria-label="后退十秒" @click="seek(position-10)">−10s</button><button class="music-play" :aria-label="playing?'暂停背景音乐':'播放背景音乐'" @click="toggle">{{playing?'Ⅱ':'▶'}}</button><button aria-label="快进十秒" @click="seek(position+10)">+10s</button><button aria-label="下一首" @click="step(1)">⏭</button></div>
      <footer><button class="music-icon" :aria-label="volume>0?'静音':'恢复音量'" @click="mute">{{volume>0?'♫':'♩'}}</button><input aria-label="背景音乐音量" type="range" min="0" max="1" step="0.01" :value="volume" @input="setVolume(Number($event.target.value))" /><small>{{Math.round(volume*100)}}%</small><button class="music-list-toggle" :aria-expanded="listVisible" @click="listVisible=!listVisible">曲目 {{tracks.length}} {{listVisible?'⌃':'⌄'}}</button></footer>
      <ol v-if="listVisible" class="music-track-list" aria-label="背景音乐曲目"><li v-for="(item,i) in tracks" :key="item.url"><button :aria-current="index===i?'true':undefined" @click="select(i,true)"><span>{{String(i+1).padStart(2,'0')}}</span>{{item.title}}<i v-if="index===i">{{playing?'♫':'·'}}</i></button></li></ol>
    </section></Transition>
  </aside>
</template>
<script setup>
import {computed,ref,watch,onMounted,onBeforeUnmount} from 'vue'
import tracks from '../assets/musicTracks.json'
import EtchedOrnament from './EtchedOrnament.vue'
const audio=ref(null),expanded=ref(false),listVisible=ref(false),playing=ref(false),error=ref(''),duration=ref(0),position=ref(0),index=ref(0),volume=ref(.3)
let lastVolume=.3,request=0
const track=computed(()=>tracks[index.value])
function remember(){try{localStorage.setItem('bs_music_preferences',JSON.stringify({index:index.value,volume:volume.value}))}catch{}}
function format(n){n=Math.max(0,Math.floor(n || 0));return `${Math.floor(n/60)}:${String(n%60).padStart(2,'0')}`}
function readDuration(){const d=audio.value?.duration;duration.value=Number.isFinite(d)?d:0}
function readTime(){position.value=audio.value?.currentTime || 0}
function seek(n){if(!audio.value || !duration.value)return;audio.value.currentTime=Math.max(0,Math.min(n,duration.value));readTime()}
function setVolume(n){volume.value=Math.max(0,Math.min(1,n));if(volume.value>0)lastVolume=volume.value;if(audio.value)audio.value.volume=volume.value;remember()}
function mute(){setVolume(volume.value>0?0:lastVolume)}
async function play(){const current=request;try{await audio.value.play();if(current===request)error.value=''}catch(e){if(current===request && e.name!=='AbortError')error.value=e.name==='NotAllowedError'?'请再次点击播放以开启声音。':'这首音乐暂时无法播放，请尝试其他曲目。'}}
function toggle(){if(playing.value){request++;audio.value.pause()}else{error.value='';play()}}
function select(i,start=false){request++;audio.value.pause();index.value=(i+tracks.length)%tracks.length;position.value=0;duration.value=0;error.value='';audio.value.src=track.value.url;audio.value.load();remember();if(start)play()}
function step(delta){select(index.value+delta,true)}
function onError(){error.value='这首音乐无法解码或读取，请更换曲目。';playing.value=false}
function openRequested(){expanded.value=!expanded.value}
function closeRequested(){expanded.value=false}
function escapePanel(event){if(event.key==='Escape' && expanded.value)expanded.value=false}
watch(expanded,open=>window.dispatchEvent(new CustomEvent('music-panel-state',{detail:{open}})))
onMounted(()=>{window.addEventListener('open-music-panel',openRequested);window.addEventListener('close-music-panel',closeRequested);window.addEventListener('keydown',escapePanel)})
onBeforeUnmount(()=>{window.removeEventListener('open-music-panel',openRequested);window.removeEventListener('close-music-panel',closeRequested);window.removeEventListener('keydown',escapePanel)})
onMounted(()=>{try{const p=JSON.parse(localStorage.getItem('bs_music_preferences') || '{}');if(Number.isInteger(p.index)&&p.index>=0&&p.index<tracks.length)index.value=p.index;if(typeof p.volume==='number'&&Number.isFinite(p.volume))volume.value=Math.max(0,Math.min(1,p.volume))}catch{}setVolume(volume.value);select(index.value)})
onBeforeUnmount(()=>{request++;audio.value?.pause()})
</script>
<style scoped>
.music-dock{position:fixed;left:25px;bottom:28px;z-index:1800;color:#4d526b;font-family:inherit}.music-dock audio{display:none}.music-pearl,.music-console{border:1px solid rgba(180,188,215,.8);background:linear-gradient(130deg,rgba(255,255,255,.9),rgba(233,235,247,.82));box-shadow:0 14px 45px #4c5a8526,inset 0 1px 0 #fff;backdrop-filter:blur(25px)}.music-pearl{display:flex;align-items:center;gap:12px;border-radius:28px;padding:13px 20px;color:inherit;cursor:pointer}.music-pearl>span:first-child{color:#ac9470;font-size:20px}.music-pearl i{font-size:10px;font-style:normal;color:#7b84a2}.music-console{width:390px;border-radius:25px;padding:22px;position:relative;isolation:isolate;-webkit-box-reflect:below 7px linear-gradient(transparent 86%,#ffffff16)}.music-console:before{content:'';position:absolute;inset:auto 10px -16px;height:35px;z-index:-1;background:radial-gradient(ellipse,#fff9,transparent 70%);filter:blur(12px);pointer-events:none}.music-console header{display:flex;gap:15px;align-items:center}.music-disc{flex:none;width:62px;height:62px;display:grid;place-items:center;font-size:28px;border-radius:50%;color:#af9470;background:repeating-radial-gradient(circle,#fff8 0 4px,#c1c6df55 5px 6px);border:1px solid #c7c9dc;box-shadow:0 0 25px #fff}.music-heading{min-width:0;flex:1}.music-heading small{font-size:10px;letter-spacing:2px;color:#978467}.music-heading strong{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:16px;margin:5px 0}.music-heading p{font-size:10px;margin:0;color:#707995;line-height:1.6}.music-console button{font-family:inherit;cursor:pointer;color:inherit;transition:background .2s,transform .2s}.music-console button:focus-visible,.music-pearl:focus-visible{outline:2px solid #9685bb;outline-offset:3px}.music-icon{border:0;background:transparent;font-size:20px;padding:5px}.music-timeline{margin:18px 0 10px}.music-console input[type=range]{width:100%;height:16px;accent-color:#a296b8;cursor:pointer}.music-timeline>div{display:flex;justify-content:space-between;color:#757e99;font-size:10px;font-variant-numeric:tabular-nums}.music-controls{display:flex;justify-content:center;align-items:center;gap:14px}.music-controls button{border:0;background:transparent;min-width:32px;padding:9px 3px;font-size:13px}.music-controls .music-play{width:46px;height:46px;border-radius:50%;background:#fff9;border:1px solid #c7c6dc;font-size:17px;color:#7f709b}.music-controls button:hover{transform:translateY(-2px);color:#857098}.music-console footer{display:flex;align-items:center;gap:8px;margin-top:12px}.music-console footer input{width:100px}.music-console footer small{font-size:10px;min-width:28px}.music-list-toggle{margin-left:auto;border:1px solid #d1d2e4;background:#fff5;border-radius:10px;padding:7px 10px;font-size:11px}.music-track-list{list-style:none;padding:9px 0 0;margin:12px 0 0;border-top:1px solid #d8d9e8;max-height:190px;overflow:auto}.music-track-list button{display:flex;align-items:center;text-align:left;width:100%;gap:10px;padding:10px;border:0;background:transparent;font-size:12px;border-radius:9px}.music-track-list button[aria-current=true]{background:#e8e4f2;color:#74658b}.music-track-list span{color:#9b92ac;font-size:10px}.music-track-list i{margin-left:auto}.spinning{animation:music-turn 22s linear infinite}@keyframes music-turn{to{transform:rotate(360deg)}}
@media(max-width:650px){.music-dock{left:12px;bottom:16px}.music-pearl{padding:11px 13px;gap:8px}.music-pearl i{display:none}.music-console{box-sizing:border-box;width:min(390px,calc(100vw - 24px));padding:18px;border-radius:21px;max-height:calc(100dvh - 100px);overflow-y:auto}.music-track-list{max-height:145px}.music-heading strong{font-size:14px}}@media(prefers-reduced-motion:reduce){.spinning{animation:none}.music-console button{transition:none}}
.music-console input[type=range]{appearance:none;-webkit-appearance:none;background:transparent;min-width:0;padding:0;border:0;box-shadow:none}.music-console input[type=range]::-webkit-slider-runnable-track{height:4px;border-radius:5px;background:#d5d2e3}.music-console input[type=range]::-webkit-slider-thumb{appearance:none;-webkit-appearance:none;width:13px;height:13px;border-radius:50%;background:#a194b5;border:2px solid #fff;margin-top:-4.5px;box-shadow:0 1px 6px #86749b44}.music-console input[type=range]::-moz-range-track{height:4px;border-radius:5px;background:#d5d2e3}.music-console input[type=range]::-moz-range-thumb{width:10px;height:10px;border-radius:50%;background:#a194b5;border:2px solid #fff}.music-console footer input{flex:1;width:100px!important;min-width:0}.music-list-toggle{flex-shrink:0;white-space:nowrap}.music-icon{flex-shrink:0}
</style>
